def dissoc(d, *keys):
    """ Return a new dict with the given key(s) removed.

    New dict has d[key] deleted for each supplied key.
    Does not modify the initial dictionary.

    >>> dissoc({'x': 1, 'y': 2}, 'y')
    {'x': 1}
    >>> dissoc({'x': 1, 'y': 2}, 'y', 'x')
    {}
    >>> dissoc({'x': 1}, 'y') # Ignores missing keys
    {'x': 1}
    """
    if isinstance(d, Mapping):
        items = [(k, v) for k, v in d.items() if k not in keys]
        try:
            return type(d)(items)
        except TypeError:
            # Some Mapping subclasses (e.g., defaultdict) have special constructors
            # Fall back to copy-and-delete approach
            pass
    d2 = copy.copy(d)
    for key in keys:
        if key in d2:
            del d2[key]
    return d2

